* { box-sizing: border-box; margin: 0; padding: 0; }

.mp-container {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  height: 100%;
  max-height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  width: 100%;
  gap: 4px;
}

.titulo { font-size: 18px; font-weight: 700; color: #3F3530; padding: 8px 8px 4px; text-transform: uppercase; letter-spacing: 0.05em; display: flex; align-items: center; gap: 8px; }
.wrap { display: flex; align-items: stretch; padding: 4px 8px 8px; gap: 6px; width: 100%; }
.card { flex: 1; min-width: 0; background: rgba(51,81,58,0.06); border-radius: 8px; padding: 10px 6px; display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 5px; }
.dot { width: 9px; height: 9px; border-radius: 50%; flex-shrink: 0; }
.lbl { font-size: 13px; color: #786F68; font-weight: 500; white-space: nowrap; display: flex; align-items: center; gap: 5px; }
.val { font-size: 22px; font-weight: 500; color: #3F3530; line-height: 1; }
.sep { width: 0.5px; background: rgba(51,81,58,0.15); align-self: stretch; flex-shrink: 0; margin: 4px 0; }
.clickable { cursor: pointer; transition: background 0.15s; }
.clickable:hover { background: rgba(51,81,58,0.12); }

.card.tooltip-total { position: relative; cursor: help; }
.card.tooltip-total:hover::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  margin-bottom: 8px;
  background: rgba(51,81,58,0.94);
  color: #fff;
  padding: 6px 10px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  z-index: 10;
  pointer-events: none;
}
.card.tooltip-total:hover::before {
  content: '';
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  margin-bottom: 2px;
  border: 5px solid transparent;
  border-top-color: rgba(51,81,58,0.94);
  z-index: 10;
  pointer-events: none;
}

.val-sub {
  font-size: 0.75em;
  opacity: 0.65;
  margin-top: 2px;
}

/* Boton "Ver caudales sectores" - a juego con la cabecera verde-bosque de marca (CRBG) */
.btn-row {
  display: flex;
  justify-content: center;
  padding: 6px 8px 8px;
}
.btn-ver-sectores {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: #ffffff;
  color: #33513A;
  border: 1px solid #33513A;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.02em;
  cursor: pointer;
  box-shadow: none;
  transition: background 0.15s ease, color 0.15s ease;
}
.btn-ver-sectores:hover {
  background: #33513A;
  color: #ffffff;
}
.btn-ver-sectores:active {
  background: #24392A;
  border-color: #24392A;
}
.btn-ver-sectores svg {
  flex-shrink: 0;
}

.info-icon {
    position: relative;
    font-size: 15px;
    font-weight: normal;
    text-transform: none;
    letter-spacing: normal;
    color: #786F68;
    cursor: help;
}
.info-icon:hover {
    color: #3F3530;
}
.info-icon:hover::after {
    content: attr(data-tooltip);
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    margin-top: 8px;
    background: rgba(51,81,58,0.94);
    color: #fff;
    padding: 6px 10px;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 400;
    line-height: 1.3;
    white-space: normal;
    width: max-content;
    max-width: 240px;
    text-align: left;
    z-index: 20;
    pointer-events: none;
}
.info-icon:hover::before {
    content: '';
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    margin-top: 2px;
    border: 5px solid transparent;
    border-bottom-color: rgba(51,81,58,0.94);
    z-index: 20;
    pointer-events: none;
}

