var currentEntity = null;

self.onInit = function() {
    var $ctx = self.ctx;
    $ctx.$container.find('.card-diaria').off('click').on('click', function(e) {
        var stateId = $(this).data('state');
        if (!stateId) return;
        var descriptors = $ctx.actionsApi.getActionDescriptors('sector_click');
        if (descriptors && descriptors.length > 0) {
            descriptors.forEach(function(desc) {
                $ctx.actionsApi.handleWidgetAction(e, desc, currentEntity, stateId, null, stateId);
            });
        }
    });
    $ctx.$container.find('#btn_ver_sectores').off('click').on('click', function(e) {
        var descriptors = $ctx.actionsApi.getActionDescriptors('ver_sectores_click');
        if (descriptors && descriptors.length > 0) {
            descriptors.forEach(function(desc) {
                $ctx.actionsApi.handleWidgetAction(e, desc, currentEntity, null, null, null);
            });
        }
    });
};

self.actionSources = function() {
    return {
        'sector_click': { name: 'Click en Sector', multiple: true },
        'ver_sectores_click': { name: 'Ver caudales sectores', multiple: false }
    };
};

// Punto de los miles a mano, con expresion regular -- no depende de que el
// navegador soporte bien toLocaleString('es-ES') (en algunos entornos no
// hace nada, se queda con el numero tal cual, sin avisar).
function fmt(n) {
    if (n === null || n === undefined || isNaN(n)) return '-';
    var redondeado = Math.round(n);
    var negativo = redondeado < 0;
    var texto = Math.abs(redondeado).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    return (negativo ? '-' : '') + texto;
}

self.onDataUpdated = function() {
    var $ctx = self.ctx;
    var data = $ctx.data;

    if (data.length > 0 && data[0].datasource && data[0].datasource.entity) {
        currentEntity = data[0].datasource.entity;
    }

    function v(key) {
        for (var i = 0; i < data.length; i++) {
            if (data[i].dataKey.name === key && data[i].data.length > 0) {
                var points = data[i].data;
                var lastPoint = points[points.length - 1];
                return fmt(parseFloat(lastPoint[1]));
            }
        }
        return '-';
    }

    var keysProyectada = [
        'media_proyectada_s0', 'media_proyectada_s1', 'media_proyectada_s2',
        'media_proyectada_s3', 'media_proyectada_s4', 'media_proyectada_s5',
        'media_proyectada_total'
    ];
    keysProyectada.forEach(function(k) { $ctx.$container.find('#val_' + k).text(v(k)); });

    // Consumo actual (caudal instantaneo, sin proyectar) por sector
    var keysCaudal = [
        'caudal_s0', 'caudal_s1', 'caudal_s2',
        'caudal_s3', 'caudal_s4', 'caudal_s5',
        'caudal_total'
    ];
    keysCaudal.forEach(function(k) { $ctx.$container.find('#val_' + k).text(v(k)); });
};

